def detect_runs(arr, minrun=32):
    runs = []
    n = len(arr)
    i = 0
    while i < n:
        run_start = i
        run_end = i + 1
        direction = 0
        while run_end < n and (arr[run_end] >= arr[run_end - 1] or arr[run_end] <= arr[run_end - 1]):
            if arr[run_end] > arr[run_end - 1]:
                direction = 1
            elif arr[run_end] < arr[run_end - 1]:
                direction = -1
            run_end += 1
        if direction == -1:
            runs.append((run_start, run_end, 'decreasing'))
        else:
            runs.append((run_start, run_end, 'increasing'))
        i = run_end
        if i < n:
            if i - run_start < minrun:
                i += minrun - (i - run_start)
    return runs

# Example
print(detect_runs([5, 4, 3, 2, 1, 6, 7, 8]))
